"""Rule book after the standards (rule catalogue): the 35 rules N1.1 ... N5.3 as plain data, plus the rule fulfilment per sheet.
No OCP imports. docs/drawing-rules.md is generated from this module:  python packages/drawing/rules.py > docs/drawing-rules.md

Kinds: N = standard rule (standard named, content after the textbook), L = textbook rule without an unambiguous clause of a standard,
P = drafting practice (numeric value chosen by us). Where the design names two kinds (e.g. "N/P"), the less assertive one applies (P before L before N).
All references to standards are textbook knowledge and not checked against the standard text."""
import sys
from dataclasses import dataclass

EVIDENCE = 'textbook knowledge, not checked against the standard text'
STAGES = ('existing', 'S0', 'S1', 'S2', 'S3', 'S4')        # measurable from this stage on
MIN_ASSIGNED = 0.8          # rules with needs_assignment are not measurable below this assignment share
CAL = 'to be calibrated'
PROJ_TOL_MM = 0.5           # N1.7: views in projection relation line up on their common model axis up to this offset (checks.projection_findings uses this value)
MIN_AXIS_MM = 5.0           # N2.2: symmetry lines shorter than this on paper (stubs on a single edge) are not generated by symmetry.add_axes, and the check never counts them as shown
PATTERN_MIN_MM = 5.0        # N4.9: characteristic length of a plane pattern at least this large on paper (checks.PATTERN_MIN_MM is the same value), otherwise a pattern detail
ZONE_OVERLAP_MM = 20.0      # N1.9: overlap of the cross axis from which a part view counts as a neighbour of one side of the assembly (checks.ZONE_OVERLAP is the same value)
GRID_LONELY_TARGET = 0.6    # N1.8: target for grid_lonely_share, blocks without an axis partner / blocks (checks.GRID_LONELY_TARGET is the same value)


def _num(x):
    """Number formatted for the rule book texts."""
    return f'{x:g}'


@dataclass(frozen=True)
class Rule:
    id: str
    group: str
    kind: str                       # 'N' | 'L' | 'P'
    norm: str                       # standard number without clause, '' if none
    statement: str
    measure: str
    codes: tuple
    severity: str                   # 'block' | 'warn' | 'metric'
    threshold: 'str | None'
    needs_assignment: bool
    stage: str                      # measurable from this stage on
    evidence: str = EVIDENCE
    producers: tuple = ()           # producers in the planner/render core (module.function), as far as present


def _r(id, kind, norm, statement, measure, codes=(), severity='warn', threshold=None, needs=False, stage='S1', producers=()):
    return Rule(id=id, group=id.split('.')[0], kind=kind, norm=norm, statement=statement, measure=measure, codes=tuple(codes),
                severity=severity, threshold=threshold, needs_assignment=needs, stage=stage, producers=tuple(producers))


