def _stage_index(stage):
    return STAGES.index(stage)


def violations(findings_by_code, assigned_share, stage_now='S0', rules_=RULES):
    """Per rule the sum of the findings of its codes; None = not measurable (no codes, stage not yet reached or assignment < MIN_ASSIGNED)."""
    now = _stage_index(stage_now)
    out = {}
    for r in rules_:
        if (not r.codes or _stage_index(r.stage) > now
                or (r.needs_assignment and (assigned_share is None or assigned_share < MIN_ASSIGNED))):
            out[r.id] = None
        else:
            out[r.id] = sum(int(findings_by_code.get(c) or 0) for c in r.codes)
    return out


def rules_ok(viol, rules_=RULES):
    """Share of the rules with value 0 among the measurable (value != None) rules, 3 digits; 'metric' rules do not count; None if none is measurable."""
    metric = {r.id for r in rules_ if r.severity == 'metric'}
    vals = [v for k, v in viol.items() if v is not None and k not in metric]
    return round(sum(1 for v in vals if v == 0) / len(vals), 3) if vals else None


def markdown():
    """docs/drawing-rules.md: table of all rules."""
    esc = lambda t: str(t).replace('|', '\\|').replace('\n', ' ')
    lines = ['# Drawing rule catalogue', '',
             'All references to standards in this rule book are textbook knowledge and not checked against the standard text. Generated from `packages/drawing/rules.py` '
             '(`python packages/drawing/rules.py`), do not edit by hand.', '',
             'Kind: N = standard rule, L = textbook rule without an unambiguous clause of a standard, P = drafting practice (numeric value chosen). '
             'Severity: block, warn or metric (measure, does not count in `rules_ok`).', '',
             '| ID | Group | Kind | Standard | Statement | Measurement | Threshold | Severity | Codes | From stage | Producers | Evidence |',
             '|---|---|---|---|---|---|---|---|---|---|---|---|']
    for r in RULES:
        lines.append('| ' + ' | '.join(esc(x) for x in (r.id, r.group, r.kind, r.norm or '–', r.statement, r.measure, r.threshold or '–', r.severity,
                                                          ', '.join(f'`{c}`' for c in r.codes) or '–', r.stage,
                                                          ', '.join(f'`{p}`' for p in r.producers) or '–', r.evidence)) + ' |')
    return '\n'.join(lines) + '\n'


if __name__ == '__main__':
    sys.stdout.buffer.write(markdown().encode('utf-8'))
